package splitpage

import (
	"flag"
	"testing"

	"github.com/subaud-tools/tools-common/wiregen"
)

var update = flag.Bool("update", false, "rewrite wire.d.ts from the Go structs")

// wireRoots are what crosses Go and the page's TypeScript: the tab calls and
// the terminal's resize message.
var wireRoots = []any{TabList{}, OpenRequest{}, SelectRequest{}, CloseRequest{}, Resize{}}

var wireOptions = wiregen.Options{
	Header: "// Generated by splitpage's wire_test.go from the Go structs in splitpage;\n" +
		"// do not edit. Regenerate: go test ./splitpage -run TestWireCommitted -update\n",
	Regenerate: "go test ./splitpage -run TestWireCommitted -update",
}

func TestWireCommitted(t *testing.T) {
	if err := wiregen.CheckCommitted("wire.d.ts", wireRoots, wireOptions, *update); err != nil {
		t.Fatal(err)
	}
}
